$_SERVER['HTTP_HOST']='127.0.0.1:8799';$_SERVER['REQUEST_URI']='/';require __DIR__.'/site/wordpress/wp-load.php';$out=['checked_at'=>gmdate('c'),'status'=>'PASS_NATIVE_WOO_REAL_LOCAL_ORDER_OBJECTS','orders'=>[],'real_charge'=>false,'email_sent'=>false,'gateway'=>'NativeWooCommerceBACSmanualtestonly','inventory_reservation_proven'=>false,'stock_management_disabled_in_this_SQLite_demo'=>true];foreach(wc_get_orders(['limit'=>2,'orderby'=>'id','order'=>'DESC']) as $o){$items=[];foreach($o->get_items() as $item){$p=$item->get_product();$items[]=['product_id'=>$p->get_id(),'virtual'=>$p->is_virtual(),'quantity'=>$item->get_quantity()];}$out['orders'][]=['id'=>$o->get_id(),'status'=>$o->get_status(),'payment_method'=>$o->get_payment_method(),'total'=>$o->get_total(),'shipping_total'=>$o->get_shipping_total(),'currency'=>$o->get_currency(),'items'=>$items];}echo wp_json_encode($out,JSON_PRETTY_PRINT|JSON_UNESCAPED_UNICODE),"\n";
